import pandas as pd
import numpy as np

# Use staged roadside CO data only; no database re-querying.
_synth_pair_df = roadside_co_paired_station_readings_df.copy()
_synth_obs_df = roadside_co_observation_df.copy()

def _synth_norm(x):
    return str(x).lower().replace(" ", "").replace("_", "").replace("-", "").replace("/", "")

def _synth_find_station_col(df):
    for c in df.columns:
        if _synth_norm(c) in ("stationid", "station"):
            return c
    for c in df.columns:
        if "station" in _synth_norm(c) and "name" not in _synth_norm(c):
            return c
    return None

def _synth_find_time_value_col(df, hour):
    # Handles wide/pivoted columns named by timestamps or strings like co_0800 / 2025-01-22 08:00:00
    candidates = []
    for c in df.columns:
        if isinstance(c, (pd.Timestamp,)):
            if c == pd.Timestamp(f"2025-01-22 {hour:02d}:00:00"):
                candidates.append(c)
        else:
            try:
                ts = pd.to_datetime(c)
                if ts == pd.Timestamp(f"2025-01-22 {hour:02d}:00:00"):
                    candidates.append(c)
                    continue
            except Exception:
                pass
            s = str(c).lower()
            ns = _synth_norm(c)
            if f"{hour:02d}:00" in s or f"{hour:02d}00" in ns or f"{hour}" in ns and "co" in ns:
                candidates.append(c)
    co_candidates = [c for c in candidates if "co" in _synth_norm(c)]
    return (co_candidates or candidates or [None])[0]

def _synth_make_wide_from_long(df):
    station_col = _synth_find_station_col(df)
    dt_col = None
    for c in df.columns:
        if pd.api.types.is_datetime64_any_dtype(df[c]) or _synth_norm(c) in ("datetime", "timestamp", "datehour", "time"):
            dt_col = c
            break
    co_col = col if "col" in globals() and col in df.columns else None
    if co_col is None:
        for c in df.columns:
            if _synth_norm(c) == "co":
                co_col = c
                break
        if co_col is None:
            for c in df.columns:
                if "co" in _synth_norm(c) and pd.api.types.is_numeric_dtype(df[c]):
                    co_col = c
                    break
    if station_col is None or dt_col is None or co_col is None:
        return None
    tmp = df[[station_col, dt_col, co_col]].copy()
    tmp[dt_col] = pd.to_datetime(tmp[dt_col])
    tmp = tmp[tmp[dt_col].isin([pd.Timestamp("2025-01-22 08:00:00"), pd.Timestamp("2025-01-22 14:00:00")])]
    if tmp.empty:
        return None
    return tmp.pivot_table(index=station_col, columns=dt_col, values=co_col, aggfunc="mean").reset_index()

_synth_wide_df = None
_synth_col_0800 = _synth_find_time_value_col(_synth_pair_df, 8)
_synth_col_1400 = _synth_find_time_value_col(_synth_pair_df, 14)

if _synth_col_0800 is not None and _synth_col_1400 is not None:
    _synth_station_col = _synth_find_station_col(_synth_pair_df)
    _synth_wide_df = _synth_pair_df.copy()
else:
    _synth_wide_df = _synth_make_wide_from_long(_synth_pair_df)
    if _synth_wide_df is None:
        _synth_wide_df = _synth_make_wide_from_long(_synth_obs_df)
    if _synth_wide_df is not None:
        _synth_station_col = _synth_find_station_col(_synth_wide_df)
        _synth_col_0800 = _synth_find_time_value_col(_synth_wide_df, 8)
        _synth_col_1400 = _synth_find_time_value_col(_synth_wide_df, 14)

if _synth_wide_df is None or _synth_col_0800 is None or _synth_col_1400 is None:
    raise ValueError(
        "Unable to identify paired 08:00 and 14:00 CO readings from staged roadside CO data. "
        f"paired columns={list(_synth_pair_df.columns)}, observation columns={list(_synth_obs_df.columns)}"
    )

_synth_complete_pairs_df = _synth_wide_df[_synth_wide_df[_synth_col_0800].notna() & _synth_wide_df[_synth_col_1400].notna()].copy()
if _synth_complete_pairs_df.empty:
    raise ValueError("Staged roadside CO data contains no complete roadside station pairs for 08:00 and 14:00 on 2025-01-22.")

mean_co_0800 = float(_synth_complete_pairs_df[_synth_col_0800].mean())
mean_co_1400 = float(_synth_complete_pairs_df[_synth_col_1400].mean())
co_difference = float(mean_co_0800 - mean_co_1400)
n_roadside_stations = int(_synth_complete_pairs_df[_synth_station_col].nunique() if _synth_station_col is not None else len(_synth_complete_pairs_df))

print("mean_co_0800 =", mean_co_0800)
print("mean_co_1400 =", mean_co_1400)
print("co_difference =", co_difference)
print("n_roadside_stations =", n_roadside_stations)
